import{_ as t,o,c as r,a5 as l}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"Spring框架中集成日志打印功能","description":"","frontmatter":{"title":"Spring框架中集成日志打印功能","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/Spring框架中集成日志打印功能.md","filePath":"posts/java快速入门/第三部分：核心 API/07-异常与线程/Spring框架中集成日志打印功能.md"}'),a={name:"posts/java快速入门/第三部分：核心 API/07-异常与线程/Spring框架中集成日志打印功能.md"};function n(g,e,p,i,s,c){return o(),r("div",null,[...e[0]||(e[0]=[l("<div><p>步骤 1：添加日志依赖 Spring Boot 默认包含SLF4J和Logback。如果你使用的是Spring Boot，你不需要额外添加依赖。如果你使用的是普通的Spring项目，你需要添加以下依赖： Maven 项目： 在你的<code>pom.xml</code>文件中添加以下依赖： &lt;dependencies&gt; &lt;!-- SLF4J API --&gt; &lt;dependency&gt; &lt;groupId&gt;org.slf4j&lt;/groupId&gt; &lt;artifactId&gt;slf4j-api&lt;/artifactId&gt; &lt;version&gt;1.7.30&lt;/version&gt; &lt;/dependency&gt; &lt;!-- Logback Classic --&gt; &lt;dependency&gt; &lt;groupId&gt;ch.qos.logback&lt;/groupId&gt; &lt;artifactId&gt;logback-classic&lt;/artifactId&gt; &lt;version&gt;1.2.3&lt;/version&gt; &lt;/dependency&gt; &lt;/dependencies&gt;</p><p>Gradle 项目： 在你的<code>build.gradle</code>文件中添加以下依赖： dependencies { implementation &#39;org.slf4j:slf4j-api:1.7.30&#39; implementation &#39;ch.qos.logback:logback-classic:1.2.3&#39; }</p><p>步骤 2：配置日志记录 Spring Boot 默认使用Logback，你可以在<code>src/main/resources</code>目录下创建一个<code>logback-spring.xml</code>文件来自定义日志配置。以下是一个示例配置： &lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&gt; &lt;configuration&gt; &lt;!-- 控制台输出 --&gt; &lt;appender name=&quot;console&quot; class=&quot;ch.qos.logback.core.ConsoleAppender&quot;&gt; &lt;encoder&gt; &lt;pattern&gt;%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt; &lt;!-- 文件输出 --&gt; &lt;appender name=&quot;file&quot; class=&quot;ch.qos.logback.core.FileAppender&quot;&gt; &lt;file&gt;app.log&lt;/file&gt; &lt;encoder&gt; &lt;pattern&gt;%d{yyyy-MM-dd HH:mm:ss} %-5level %logger{36} - %msg%n&lt;/pattern&gt; &lt;/encoder&gt; &lt;/appender&gt; &lt;!-- 根日志记录器，配置日志级别和附加器 --&gt; &lt;root level=&quot;info&quot;&gt; &lt;appender-ref ref=&quot;console&quot;/&gt; &lt;appender-ref ref=&quot;file&quot;/&gt; &lt;/root&gt; &lt;/configuration&gt; 步骤 3：使用日志记录 在你的Spring Boot应用中，你可以使用SLF4J来记录日志。以下是一个示例控制器，展示如何使用SLF4J记录日志： package com.example.demo.controller; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RequestParam; import org.springframework.web.bind.annotation.RestController; @RestController public class ExampleController { private static final Logger logger = LoggerFactory.getLogger(ExampleController.class); @GetMapping(&quot;/example&quot;) public ResponseEntity&lt;String&gt; example(@RequestParam(name = &quot;name&quot;, required = false, defaultValue = &quot;World&quot;) String name) { logger.info(&quot;Received request with parameter: name={}&quot;, name); try { // 模拟业务逻辑 if (&quot;error&quot;.equalsIgnoreCase(name)) { throw new RuntimeException(&quot;Simulated exception&quot;); } String response = &quot;Hello, &quot; + name + &quot;!&quot;; logger.info(&quot;Response: {}&quot;, response); return ResponseEntity.ok(response); } catch (Exception e) { logger.error(&quot;An error occurred&quot;, e); return ResponseEntity.status(500).body(&quot;Internal Server Error&quot;); } } } 在这个示例中，我们创建了一个简单的Spring Boot控制器<code>ExampleController</code>，并使用SLF4J记录日志：</p><ul><li><code>logger.info</code> 用于记录信息性日志。</li><li><code>logger.error</code> 用于记录错误日志。 步骤 4：运行你的应用程序 运行你的Spring Boot应用程序，然后访问<code>http://localhost:8080/example?name=YourName</code>，你将在控制台和日志文件中看到日志输出。 访问示例</li><li>正常请求：<code>http://localhost:8080/example?name=YourName</code></li><li>日志输出示例： 2023-07-10 10:00:00 INFO ExampleController - Received request with parameter: name=YourName 2023-07-10 10:00:00 INFO ExampleController - Response: Hello, YourName!</li><li>触发异常请求：<code>http://localhost:8080/example?name=error</code></li><li>日志输出示例： 2023-07-10 10:00:00 INFO ExampleController - Received request with parameter: name=error 2023-07-10 10:00:00 ERROR ExampleController - An error occurred java.lang.RuntimeException: Simulated exception at com.example.demo.controller.ExampleController.example(ExampleController.java:18) ... 通过以上步骤，你就可以在Spring框架中集成日志记录功能，并通过SLF4J记录各种级别的日志信息。</li></ul></div>",1)])])}const u=t(a,[["render",n]]);export{m as __pageData,u as default};
